const apiKey = env.get('INGEST_API_KEY');
const incomingKey = msg.req?.headers?.['x-api-key'] || '';
if (!apiKey || incomingKey !== apiKey) {
    msg.res.status(401).end(JSON.stringify({ error: 'Unauthorized' }));
    return null;
}

if (!msg.payload || !Array.isArray(msg.payload)) {
    msg.res.status(400).end(JSON.stringify({ error: 'Payload must be a JSON array' }));
    return null;
}

msg._ldiBatch = [];
msg.payload.forEach(function (item, idx) {
    if (!item || !item.eqp_id) return;
    msg._ldiBatch.push({
        eqp_id: String(item.eqp_id),
        factory: String(item.factory || ''),
        process: String(item.process || ''),
        mo: String(item.mo || ''),
        fpn: String(item.fpn || ''),
        layer_name: String(item.layer_name || ''),
        resist_dosage: Number(item.resist_dosage) || null,
        scale_x: Number(item.scale_x) || null,
        scale_y: Number(item.scale_y) || null,
        temperature: Number(item.temperature) || null,
        humidity: Number(item.humidity) || null,
        scan_speed: Number(item.scan_speed) || null,
        air_vacuum: Number(item.air_vacuum) || null,
        thickness: Number(item.thickness) || null,
        board_no: parseInt(item.board_no) || null,
        total_board: parseInt(item.total_board) || null,
        total_time: Number(item.total_time) || null,
        filmno: String(item.filmno || ''),
        board_id: String(item.board_id || ''),
        resist: String(item.resist || ''),
        state: item.state !== false,
        scale_mode: String(item.scale_mode || ''),
        pe_1: Number(item.pe_1) || null,
        pe_2: Number(item.pe_2) || null,
        pe_3: Number(item.pe_3) || null,
        pe_4: Number(item.pe_4) || null,
        pe_5: Number(item.pe_5) || null,
        pe_6: Number(item.pe_6) || null,
        je_1: Number(item.je_1) || null,
        je_2: Number(item.je_2) || null,
        je_3: Number(item.je_3) || null,
        je_4: Number(item.je_4) || null,
        pe_setting: Number(item.pe_setting) || null,
        je_setting: Number(item.je_setting) || null,
        log_id: String(item.log_id || (item.eqp_id + '-' + Date.now() + '-' + idx))
    });
});

return msg;

const pool = global.get('pgPool');
const rows = msg._ldiBatch || [];
if (!pool) {
    msg.res.status(500).end(JSON.stringify({ error: 'DB pool unavailable' }));
    return null;
}
if (rows.length === 0) {
    msg.res.status(200).end(JSON.stringify({ ok: true, count: 0 }));
    return null;
}
const cols = ['factory','process','eqp_id','mo','fpn','layer_name','resist_dosage','scale_x','scale_y','temperature','humidity','scan_speed','air_vacuum','thickness','board_no','total_board','total_time','filmno','board_id','resist','state','scale_mode','pe_1','pe_2','pe_3','pe_4','pe_5','pe_6','je_1','je_2','je_3','je_4','pe_setting','je_setting','log_id'];
const placeholders = rows.map(function (_, i) {
    const b = i * cols.length;
    const ph = cols.map(function (_, j) { return '$' + (b + j + 1); }).join(',');
    return '(NOW(),' + ph + ')';
}).join(',');
const params = [];
for (const r of rows) {
    for (const c of cols) params.push(r[c]);
}
const sql = 'INSERT INTO public.ldi_data ("time",' + cols.join(',') + ') VALUES ' + placeholders;
pool.query(sql, params, function (err) {
    if (err) {
        node.error('LDI batch INSERT failed: ' + err.message);
        msg.res.status(500).end(JSON.stringify({ error: 'DB insert failed' }));
        return;
    }
    node.log('LDI batch INSERT ok: ' + rows.length + ' rows');
    msg.res.status(200).end(JSON.stringify({ ok: true, count: rows.length }));
});
return null;

const err = msg.error?.message || 'Unknown error';
node.error('LDI INSERT failed: ' + err);
msg.res.status(500).end(JSON.stringify({ error: err }));
return null;
